"""Semantic-drift guard for D-012 (executing SQL regenerated by sqlglot).

Each expression runs twice on the demo workspace: raw (trusted test input, straight to the
sandbox) and through validate_sql -> apply_row_cap. Values and column types must match; a
function whose meaning changes in the round trip must be removed from the allowlist.
"""

from __future__ import annotations

import math
from typing import Any

from sqlalchemy.orm import Session

from app.services.execution.executor import ExecutionError, execute_sql
from app.services.execution.service import run_query
from app.services.schema.cards import load_workspace_schema

