def _norm(v: Any) -> Any:
    if isinstance(v, float):
        return None if math.isnan(v) else round(v, 9)
    if isinstance(v, list):
        return [_norm(x) for x in v]
    if isinstance(v, dict):
        return {k: _norm(x) for k, x in v.items()}
    return v


def _drift(db: Session, ws: str, sql: str) -> str | None:
    schema = load_workspace_schema(db, ws).allowed()
    try:
        raw = execute_sql(ws, sql, row_cap=100, timeout_s=10)
    except ExecutionError:
        return None  # not valid DuckDB to begin with; nothing to compare
    try:
        via = run_query(ws, sql, schema, row_cap=100)
    except Exception as e:  # rejected or broken by the round trip
        return f"{sql!r}: round trip failed: {e}"
    if raw.column_types != via.column_types:
        return f"{sql!r}: type drift {raw.column_types} vs {via.column_types} -> {via.sql}"
    if [[_norm(v) for v in r] for r in raw.rows] != [[_norm(v) for v in r] for r in via.rows]:
        return f"{sql!r}: value drift -> {via.sql}"
    return None


def test_row_expression_roundtrip(db: Session, demo_ws: str) -> None:
    failures = [
        f
        for expr in ROW_EXPRS
        if (
            f := _drift(
                db, demo_ws, f"SELECT {expr} AS v FROM transactions ORDER BY txn_id LIMIT 40"
            )
        )
    ]
    assert not failures, chr(10).join(failures)


def test_aggregate_roundtrip(db: Session, demo_ws: str) -> None:
    failures = [
        f
        for expr in AGG_EXPRS
        if (f := _drift(db, demo_ws, f"SELECT {expr} AS v FROM transactions"))
    ]
    assert not failures, chr(10).join(failures)
